    prefix = name + '_'
    try:
        existing = [f for f in os.listdir(BACKUP_DIR) if f.startswith(prefix) and f.endswith('.bak')]
        if len(existing) > 10:
            existing.sort()
            for old in existing[:-10]:
                try:
                    os.remove(os.path.join(BACKUP_DIR, old))
                except Exception:
                    pass
    except Exception:
        pass
    return out

