def apply_patch(raw):
    # B12: замок от двойного клика
    if not PATCH_LOCK.acquire(blocking=False):
        return {'success': False, 'error': 'Другой патч уже применяется. Подождите.'}
    try:
        return _apply_patch_inner(raw)
    finally:
        PATCH_LOCK.release()


